'use client'

import * as React from 'react'
import { MainLayout } from './components/layout/MainLayout'
import { ContentCard } from './components/cards/ContentCard'
import content from './data/content.json'
import type { ContentData, Post } from './types/content'
import { useScroll, motion } from 'framer-motion'
import { CaretUp, CaretDown, Heart, Share } from '@phosphor-icons/react'
import {
    Tooltip,
    TooltipContent,
    TooltipProvider,
    TooltipTrigger,
} from "@/app/components/ui/tooltip"

export default function HomePage() {
    const { posts } = content as ContentData
    const containerRef = React.useRef<HTMLDivElement>(null)
    const { scrollY } = useScroll({ container: containerRef })
    const [currentIndex, setCurrentIndex] = React.useState(0)

    const handleNext = React.useCallback((index: number) => {
        const nextIndex = Math.min(index + 1, posts.length - 1)
        setCurrentIndex(nextIndex)
        const nextElement = document.querySelector(`#post-${nextIndex}`)
        if (nextElement && containerRef.current) {
            nextElement.scrollIntoView({ behavior: 'instant' })
        }
    }, [posts.length])

    const handlePrevious = React.useCallback((index: number) => {
        const prevIndex = Math.max(index - 1, 0)
        setCurrentIndex(prevIndex)
        const prevElement = document.querySelector(`#post-${prevIndex}`)
        if (prevElement && containerRef.current) {
            prevElement.scrollIntoView({ behavior: 'instant' })
        }
    }, [])

    // Function to determine if a post is the next one
    const isNextPost = React.useCallback((index: number) => {
        return index === currentIndex + 1
    }, [currentIndex])

    return (
        <MainLayout>
            <motion.div
                ref={containerRef}
                className="h-[100dvh] w-full overflow-y-auto overflow-x-hidden snap-y snap-mandatory scrollbar-none"
                style={{
                    WebkitOverflowScrolling: 'touch'
                }}
            >
                {posts.map((post: Post, index: number) => (
                    <motion.div
                        key={post.id}
                        id={`post-${index}`}
                        className="relative w-full snap-start snap-always"
                        initial={{ opacity: 0, scale: 0.95 }}
                        whileInView={{
                            opacity: 1,
                            scale: 1,
                            transition: {
                                type: "spring",
                                stiffness: 500,
                                damping: 50,
                                mass: 0.1,
                                velocity: 5
                            }
                        }}
                        viewport={{ once: true }}
                    >
                        <ContentCard
                            id={post.id}
                            title={post.title}
                            shortDescription={post.shortDescription}
                            longDescription={post.longDescription}
                            sources={post.sources}
                            lummiSearchQueries={post.lummiSearchQueries}
                            icon={post.icon}
                            stats={post.stats}
                            onNext={() => handleNext(index)}
                            onPrevious={() => handlePrevious(index)}
                            isNext={isNextPost(index)}
                        />

                        {/* Card Actions */}
                        <div className="hidden md:flex absolute right-[-80px] bottom-[5vh] flex-col gap-4">
                            <TooltipProvider delayDuration={0}>
                                <Tooltip>
                                    <TooltipTrigger asChild>
                                        <button className="group flex items-center justify-center">
                                            <div className="rounded-full bg-background/80 p-3 backdrop-blur transition-colors group-hover:bg-background/90">
                                                <Heart weight="regular" className="h-6 w-6 text-foreground" />
                                            </div>
                                        </button>
                                    </TooltipTrigger>
                                    <TooltipContent side="right" align="center" sideOffset={5}>
                                        <span className="text-sm font-medium">Like</span>
                                    </TooltipContent>
                                </Tooltip>

                                <Tooltip>
                                    <TooltipTrigger asChild>
                                        <button className="group flex items-center justify-center">
                                            <div className="rounded-full bg-background/80 p-3 backdrop-blur transition-colors group-hover:bg-background/90">
                                                <Share weight="regular" className="h-6 w-6 text-foreground" />
                                            </div>
                                        </button>
                                    </TooltipTrigger>
                                    <TooltipContent side="right" align="center" sideOffset={5}>
                                        <span className="text-sm font-medium">Share</span>
                                    </TooltipContent>
                                </Tooltip>
                            </TooltipProvider>
                        </div>
                    </motion.div>
                ))}

                {/* Navigation Controls */}
                <motion.div
                    initial={{ opacity: 1 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    className="fixed right-6 top-1/2 -translate-y-1/2 z-50 flex flex-col gap-4"
                    style={{
                        marginTop: "calc(-60px)" // Offset for the top bar height
                    }}
                >
                    <button
                        onClick={() => handlePrevious(currentIndex)}
                        className="p-3 rounded-full bg-background/80 backdrop-blur hover:bg-background/90 transition-colors disabled:opacity-50"
                        disabled={currentIndex === 0}
                    >
                        <CaretUp weight="bold" className="h-6 w-6 text-foreground" />
                    </button>
                    <button
                        onClick={() => handleNext(currentIndex)}
                        className="p-3 rounded-full bg-background/80 backdrop-blur hover:bg-background/90 transition-colors disabled:opacity-50"
                        disabled={currentIndex === posts.length - 1}
                    >
                        <CaretDown weight="bold" className="h-6 w-6 text-foreground" />
                    </button>
                </motion.div>
            </motion.div>
        </MainLayout>
    )
}

export function getDatabaseUrl() {
    if (process.env.NODE_ENV === 'production') {
        return process.env.DATABASE_URL
    }

    // Use direct connection in development
    return process.env.DATABASE_URL_DIRECT || process.env.DATABASE_URL
}

